#include <windows.h>
#include <cmath>
#include <vector>
#include <algorithm>

struct Vec3 {
    float x, y, z;
    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}
    Vec3 operator-(const Vec3& o) const { return Vec3(x - o.x, y - o.y, z - o.z); }
    Vec3 operator+(const Vec3& o) const { return Vec3(x + o.x, y + o.y, z + o.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    float Length() const { return sqrtf(x * x + y * y + z * z); }
};

struct Vec2 {
    float x, y;
    Vec2() : x(0), y(0) {}
    Vec2(float x, float y) : x(x), y(y) {}
    Vec2 operator-(const Vec2& o) const { return Vec2(x - o.x, y - o.y); }
    Vec2 operator+(const Vec2& o) const { return Vec2(x + o.x, y + o.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    float Length() const { return sqrtf(x * x + y * y); }
};

struct Matrix4x4 {
    float m[4][4];
    Matrix4x4() { memset(m, 0, sizeof(m)); }
};

struct AimContext {
    Vec3 cameraPos;
    Matrix4x4 viewMatrix;
    Matrix4x4 projMatrix;
    int screenWidth;
    int screenHeight;
    Vec2 crosshairPos;
    Vec2 lastDelta;
    float smoothFactor;
};

bool WorldToScreen(const Vec3& worldPos, const AimContext& ctx, Vec2& screenPos) {
    Vec3 viewPos;
    viewPos.x = worldPos.x * ctx.viewMatrix.m[0][0] + worldPos.y * ctx.viewMatrix.m[0][1] + 
                worldPos.z * ctx.viewMatrix.m[0][2] + ctx.viewMatrix.m[0][3];
    viewPos.y = worldPos.x * ctx.viewMatrix.m[1][0] + worldPos.y * ctx.viewMatrix.m[1][1] + 
                worldPos.z * ctx.viewMatrix.m[1][2] + ctx.viewMatrix.m[1][3];
    viewPos.z = worldPos.x * ctx.viewMatrix.m[2][0] + worldPos.y * ctx.viewMatrix.m[2][1] + 
                worldPos.z * ctx.viewMatrix.m[2][2] + ctx.viewMatrix.m[2][3];
    float w = worldPos.x * ctx.viewMatrix.m[3][0] + worldPos.y * ctx.viewMatrix.m[3][1] + 
              worldPos.z * ctx.viewMatrix.m[3][2] + ctx.viewMatrix.m[3][3];

    if (w < 0.1f) return false;

    Vec3 clipPos;
    clipPos.x = viewPos.x * ctx.projMatrix.m[0][0] + viewPos.y * ctx.projMatrix.m[0][1] + 
                viewPos.z * ctx.projMatrix.m[0][2] + w * ctx.projMatrix.m[0][3];
    clipPos.y = viewPos.x * ctx.projMatrix.m[1][0] + viewPos.y * ctx.projMatrix.m[1][1] + 
                viewPos.z * ctx.projMatrix.m[1][2] + w * ctx.projMatrix.m[1][3];
    clipPos.z = viewPos.x * ctx.projMatrix.m[2][0] + viewPos.y * ctx.projMatrix.m[2][1] + 
                viewPos.z * ctx.projMatrix.m[2][2] + w * ctx.projMatrix.m[2][3];
    float clipW = viewPos.x * ctx.projMatrix.m[3][0] + viewPos.y * ctx.projMatrix.m[3][1] + 
                  viewPos.z * ctx.projMatrix.m[3][2] + w * ctx.projMatrix.m[3][3];

    if (clipW < 0.1f) return false;

    Vec3 ndc;
    ndc.x = clipPos.x / clipW;
    ndc.y = clipPos.y / clipW;
    ndc.z = clipPos.z / clipW;

    screenPos.x = (ndc.x + 1.0f) * 0.5f * ctx.screenWidth;
    screenPos.y = (1.0f - ndc.y) * 0.5f * ctx.screenHeight;

    return (ndc.z >= 0.0f && ndc.z <= 1.0f);
}

Vec2 SmoothDelta(const Vec2& targetDelta, const Vec2& lastDelta, float smoothFactor) {
    return lastDelta + (targetDelta - lastDelta) * smoothFactor;
}

bool ComputeAimDelta(const std::vector<Vec3>& entityHeadPositions, AimContext& ctx, Vec2& outDelta) {
    const float maxConeRadius = 240.0f;
    float closestDist = maxConeRadius + 1.0f;
    Vec2 bestTarget(0, 0);
    bool foundTarget = false;

    for (const Vec3& headPos : entityHeadPositions) {
        Vec2 screenPos;
        if (!WorldToScreen(headPos, ctx, screenPos)) {
            continue;
        }

        Vec2 delta = screenPos - ctx.crosshairPos;
        float dist = delta.Length();

        if (dist < maxConeRadius && dist < closestDist) {
            closestDist = dist;
            bestTarget = delta;
            foundTarget = true;
        }
    }

    if (!foundTarget) {
        outDelta = Vec2(0, 0);
        ctx.lastDelta = outDelta;
        return false;
    }

    outDelta = SmoothDelta(bestTarget, ctx.lastDelta, ctx.smoothFactor);
    ctx.lastDelta = outDelta;
    return true;
}

#ifdef AIM_STANDALONE

int main() {
    AimContext ctx;
    ctx.cameraPos = Vec3(0, 0, 0);
    ctx.screenWidth = 1920;
    ctx.screenHeight = 1080;
    ctx.crosshairPos = Vec2(960, 540);
    ctx.smoothFactor = 0.3f;
    ctx.lastDelta = Vec2(0, 0);

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            ctx.viewMatrix.m[i][j] = (i == j) ? 1.0f : 0.0f;
            ctx.projMatrix.m[i][j] = (i == j) ? 1.0f : 0.0f;
        }
    }

    std::vector<Vec3> entities;
    entities.push_back(Vec3(100, 180, 500));
    entities.push_back(Vec3(-80, 170, 450));
    entities.push_back(Vec3(50, 175, 600));

    Vec2 aimDelta;
    if (ComputeAimDelta(entities, ctx, aimDelta)) {
        printf("Aim delta: (%.2f, %.2f)\n", aimDelta.x, aimDelta.y);
    } else {
        printf("No target in cone\n");
    }

    return 0;
}

#endif
